args <- commandArgs(TRUE);stopifnot(length(args)==2L)
out <- args[1];repo <- args[2];dir.create(out,recursive=TRUE)
src <- jsonlite::fromJSON('/opt/sceptre/source.json')
stopifnot(identical(src$sceptre_archive_sha256,'f41a8fb7e1bc10366e8efcc7a31644d4c8356bc4eca8adda9ca949c951de4fb4'),identical(src$object_schema,7L),as.character(packageVersion('DropletUtils'))=='1.30.0')
source(file.path(repo,'bin/pipeline.R')) # Actual pipeline eager namespace bootstrap; no warning suppression.
source(file.path(repo,'tests/fixture.R'))
f<-pipeline_fixture(moi='low',control='complement',mechanism='permutations')
y<-sceptre::get_response_matrix(f$object);g<-sceptre::get_grna_matrix(f$object)
meta<-as.data.frame(SummarizedExperiment::rowData(SingleCellExperiment::altExp(sceptre::get_screen_experiment(f$object),'gRNA')))
meta$grna_id<-rownames(g)
cov<-sceptre::get_cell_covariates(f$object)[,c('batch','z'),drop=FALSE]
x<-Matrix::Matrix(rbind(as.matrix(y),as.matrix(g)),sparse=TRUE)
h5<-file.path(out,'raw-10x.h5')
DropletUtils::write10xCounts(h5,x,gene.id=rownames(x),gene.symbol=rownames(x),gene.type=c(rep('Gene Expression',nrow(y)),rep('CRISPR Guide Capture',nrow(g))),version='3',type='hdf5')
disk<-sceptre::import_data_from_10x(h5,'low',meta,file.path(out,'native'),extra_covariates=cov)
plain<-function(x){if(is.data.frame(x)){attr(x,'.internal.selfref')<-NULL;for(i in seq_along(x))x[[i]]<-plain(x[[i]]);return(x)};if(is.list(x))return(lapply(x,plain));x}
stopifnot(identical(as.matrix(sceptre::get_response_matrix(disk)),as.matrix(y)),identical(as.matrix(sceptre::get_grna_matrix(disk)),as.matrix(g)),identical(plain(sceptre::get_cell_covariates(disk)),plain(sceptre::get_cell_covariates(f$object))))
cat('PASS public raw10x HDF5 source import exact counts, names and covariates\n')
paths<-function(m)unique(unlist(DelayedArray::seedApply(m,function(s)if(isS4(s)&&'filepath'%in%slotNames(s))as.character(slot(s,'filepath'))else character()),use.names=FALSE))
yd<-sceptre::get_response_matrix(disk);gd<-sceptre::get_grna_matrix(disk)
original<-paths(yd);stopifnot(length(original)==1L,identical(original,paths(gd)))
saved<-file.path(out,'saved.rds');sceptre::write_sceptre_object(disk,saved)
moved<-file.path(out,'relocated.h5');stopifnot(file.copy(original,moved));unlink(original);stopifnot(!file.exists(original))
relocate<-function(m)DelayedArray::modify_seeds(m,function(s){if(isS4(s)&&'filepath'%in%slotNames(s))slot(s,'filepath')<-normalizePath(moved);s})
reopened<-sceptre::read_sceptre_object(saved,relocate(yd),relocate(gd))
stopifnot(identical(as.matrix(sceptre::get_response_matrix(reopened)),as.matrix(y)),identical(as.matrix(sceptre::get_grna_matrix(reopened)),as.matrix(g)))
cat('PASS shared native backing public reopen/relocation with original file absent\n')
run<-function(o){set.seed(271828);o<-do.call(sceptre::set_analysis_parameters,c(list(o),f$config$analysis));o<-do.call(sceptre::assign_grnas,c(list(o,parallel=FALSE,print_progress=FALSE),f$config$assignment));o<-do.call(sceptre::run_qc,c(list(o),f$config$qc));o<-sceptre::run_discovery_analysis(o,parallel=FALSE,print_progress=FALSE,output_amount=2L);list(object=o,rng=.Random.seed)}
ram<-run(f$object);backed<-run(reopened)
stopifnot(identical(plain(sceptre::get_result(ram$object,'run_discovery_analysis')),plain(sceptre::get_result(backed$object,'run_discovery_analysis'))),identical(ram$rng,backed$rng),identical(sceptre::get_grna_assignments(ram$object),sceptre::get_grna_assignments(backed$object)))
cat('PASS imported-relocated nativeHDF5 discovery exact public result/assignments/final RNG versus RAM\n')
receipt<-list(kind='floor-native-10x-hdf5-capability-probe',status='PASS',archive=src$sceptre_archive_sha256,source=src$sceptre_commit,R=R.version.string,platform=R.version$platform,DropletUtils=as.character(packageVersion('DropletUtils')),read10xCounts_formals=names(formals(DropletUtils::read10xCounts)),gates=c('raw10x-HDF5-exact-import','shared-native-backing-relocation-original-absent','RAM-versus-imported-relocated-discovery-public-result-assignments-RNG'),dimensions=list(response=dim(y),grna=dim(g)),limits='One bounded fixture; original15package tests remain skipped and are not claimed executed. No scale, all-reader-edgecase or alternative runtime qualification.')
receipt$runtime_versions<-vapply(c('DropletUtils','HDF5Array','beachmat','beachmat.hdf5','Matrix','DelayedArray','SingleCellExperiment'),function(p)as.character(packageVersion(p)),character(1))
receipt$bootstrap_sha256<-digest::digest(file=file.path(repo,'bin/pipeline.R'),algo='sha256')
receipt$fixture_sha256<-digest::digest(file=file.path(repo,'tests/fixture.R'),algo='sha256')
writeLines(capture.output(sessionInfo()),file.path(out,'session.txt'))
jsonlite::write_json(receipt,file.path(out,'receipt.json'),auto_unbox=TRUE,pretty=TRUE)
